<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>롯데월드타워 건축 설계 과정</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 0; padding: 0; display: flex; flex-direction: column; align-items: center; background-color: #f0f0f0; }
        #container { display: flex; flex-direction: column; align-items: center; margin-top: 20px; }
        #info { margin-bottom: 20px; }
        #info h1 { margin: 0; }
        #info p { margin: 5px 0; }
        #controls { margin-bottom: 20px; }
        #controls button { margin: 5px; padding: 10px; cursor: pointer; }
        #canvas-container { width: 80%; height: 600px; background-color: #fff; }
        @media (max-width: 600px) {
            #canvas-container { width: 95%; height: 400px; }
        }
    </style>
</head>
<body>
    <div id="container">
        <div id="info">
            <h1>롯데월드타워 건축 설계 과정</h1>
            <p>높이: 555m, 지상 123층</p>
            <p>원 설계사: <a href="https://www.kpf.com/project/lotte-world-tower" target="_blank">KPF</a></p>
            <p>구조 설계사: <a href="https://www.lera.com/lotte-world-tower" target="_blank">LERA</a></p>
        </div>
        <div id="controls">
            <button onclick="showDesignStage(0)">초기 설계</button>
            <button onclick="showDesignStage(1)">중간 설계</button>
            <button onclick="showDesignStage(2)">최종 설계</button>
            <button onclick="resetView()">시점 초기화</button>
        </div>
        <div id="canvas-container"></div>
    </div>
    <script src="../runtime/three-runtime.js"></script>
    <script>
        const container = document.getElementById('canvas-container');
        const width = container.clientWidth;
        const height = container.clientHeight;

        let scene, camera, renderer, controls, currentModel;

        function init() {
            scene = new THREE.Scene();
            camera = new THREE.PerspectiveCamera(75, width / height, 0.1, 1000);
            renderer = new THREE.WebGLRenderer();
            renderer.setSize(width, height);
            container.appendChild(renderer.domElement);

            controls = new THREE.OrbitControls(camera, renderer.domElement);
            camera.position.set(0, 200, 500);
            controls.update();

            window.addEventListener('resize', onWindowResize, false);
        }

        function onWindowResize() {
            camera.aspect = container.clientWidth / container.clientHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(container.clientWidth, container.clientHeight);
            render();
        }

        function render() {
            renderer.render(scene, camera);
        }

        function createModel(stage) {
            if (currentModel) scene.remove(currentModel);

            currentModel = new THREE.Group();

            const geometry = new THREE.BoxGeometry(1, 1, 1);
            const material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });

            for (let i = 0; i < 123; i++) {
                const cube = geometry.clone();
                const mesh = new THREE.Mesh(cube, material);
                mesh.position.y = i * 5;
                mesh.scale.set(100 - i * 0.5, 100 - i * 0.5, 100 - i * 0.5);
                currentModel.add(mesh);
            }

            if (stage > 0) {
                const topGeometry = new THREE.CylinderGeometry(50, 20, 50, 32);
                const topMesh = new THREE.Mesh(topGeometry, material);
                topMesh.position.y = 600;
                currentModel.add(topMesh);
            }

            scene.add(currentModel);
            render();
        }

        function showDesignStage(stage) {
            createModel(stage);
        }

        function resetView() {
            camera.position.set(0, 200, 500);
            controls.update();
            render();
        }

        init();
        showDesignStage(2); // 초기에 최종 설계 모델 표시
    </script>
</body>
</html>
